QUESTION_KINDS = [
    ("identity","evidence","validation"), ("definition","authority","interoperability"),
    ("relationship","temporal","access"), ("requirement","decision","exception"),
    ("ownership","provenance","privacy"), ("classification","quality","security"),
    ("composition","measurement","validation"), ("state","lifecycle","retention"),
]

def make_finding(raw, index):
    fid, name, description, refs, value_kind, required = raw
    kinds = QUESTION_KINDS[index % len(QUESTION_KINDS)]
    return {
        "id":fid,"name":name,"description":description,"source_refs":refs,
        "questions":[
            {"id":fid+"-q01","text":f"What identities, roles, versions, scope and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers and roles","versions and profiles","scope and values","explicit unknowns"]},
            {"id":fid+"-q02","text":f"Which statement, authority, cryptographic evidence, event time and knowledge time support {name.lower()}?","kind":kinds[1],"answer_data":["statement and authority","proof or status evidence","event and knowledge time","assumptions"]},
            {"id":fid+"-q03","text":f"How may {name.lower()} be validated, contested, corrected, superseded, retained and disclosed without exposing a witness or equating verification with authorization?","kind":kinds[2],"answer_data":["validation","contest and correction","successor history","witness exclusion","decision boundary"]},
        ],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured proof-binding data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing attestation record for "+name.lower()+" with statement, suite, event and knowledge time, provenance and disclosure marking.","media_or_form":["logical verification or attestation assertion","cryptographic proof, status or verifier-evidence reference"],"serial":True,"identity_strategy":"Attestation binding identifier plus "+fid+" assertion or event identifier; subject name, predicate, proof value, date and digest never identify the binding alone.","source_refs":refs}],
        "inline_only_rationale":None,
    }

def structure():
    cursor = 0
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        made_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made = []
            for raw in findings:
                made.append(make_finding(raw, cursor)); cursor += 1
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":made})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

